def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Lines are split on the first '='. Whitespace around the key and the
    value is ignored. Blank lines and lines starting with '#' are skipped.
    Returns an empty string when the key is absent. Never reads files.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_returns_value_for_present_key() -> None:
    text = "host=localhost\nport=8080\n"
    assert config_value(text, "port") == "8080"


def test_returns_empty_string_for_absent_key() -> None:
    text = "host=localhost\nport=8080\n"
    assert config_value(text, "user") == ""


def test_returns_empty_string_for_empty_text() -> None:
    assert config_value("", "host") == ""


def test_splits_on_first_equals_only() -> None:
    text = "expr=a=b=c\n"
    assert config_value(text, "expr") == "a=b=c"


def test_strips_whitespace_around_key_and_value() -> None:
    text = "  host  =   localhost  \n"
    assert config_value(text, "host") == "localhost"


def test_skips_comment_lines() -> None:
    text = "# host=wrong\nhost=right\n"
    assert config_value(text, "host") == "right"


def test_skips_blank_lines() -> None:
    text = "\n\nhost=localhost\n\n"
    assert config_value(text, "host") == "localhost"


def test_key_match_is_exact_not_prefix() -> None:
    text = "hostname=example\n"
    assert config_value(text, "host") == ""


def test_empty_value_is_returned_as_empty_string() -> None:
    text = "token=\n"
    assert config_value(text, "token") == ""
